import AppKit

/// Brand glyphs for known CLI agents, rasterized from the
/// vector sources at exact display multiples of the 18pt sidebar icon
/// slot (36/54/72px = 2x/3x/4x). No intermediate resample: the reps
/// map 1:1 onto the backing store, so thin-stroke marks stay crisp.
///
/// Primary set: tty7's curated agent icons
/// (herdration/tty7/assets/icons/agents — official marks, MIT where
/// third-party, normalized to a 24x24 box with a #FF0000 placeholder
/// fill that we re-black before rasterizing). qwen/kimi/cline come
/// from Simple Icons. All shapes are knocked to alpha so the rows'
/// existing tint applies.
enum AgentBrandIcons {
    static let pngs: [String: [Int: String]] = [
        "amp": [2: "", 3: "", 4: ""],
        "claude": [2: "", 3: "", 4: ""],
        "cline": [2: "", 3: "", 4: ""],
        "codex": [2: "", 3: "", 4: ""],
        "copilot": [2: "", 3: "", 4: ""],
        "cursor": [2: "", 3: "", 4: ""],
        "droid": [2: "", 3: "", 4: ""],
        "gemini": [2: "", 3: "", 4: ""],
        "goose": [2: "", 3: "", 4: ""],
        "grok": [2: "", 3: "", 4: ""],
        "kimi": [2: "", 3: "", 4: ""],
        "omp": [2: "", 3: "", 4: ""],
        "opencode": [2: "", 3: "", 4: ""],
        "pi": [2: "", 3: "", 4: ""],
        "qwen": [2: "", 3: "", 4: ""],
    ]

    static func image(for kind: String?) -> NSImage? {
        guard let key = kind?.lowercased(), !key.isEmpty,
              let scales = pngs[key] else { return nil }
        let image = NSImage(size: NSSize(width: 18, height: 18))
        for (_, b64) in scales.sorted(by: { $0.key < $1.key }) {
            guard let data = Data(base64Encoded: b64),
                  let rep = NSBitmapImageRep(data: data) else { continue }
            rep.size = NSSize(width: 18, height: 18)
            image.addRepresentation(rep)
        }
        image.isTemplate = true
        return image
    }
}
